function pluginHalloween(){
    function show(){
        let html = $(`<div class="halloween">
            <div class="halloween__image">
                <img class="halloween__img">
            </div>
            <div class="halloween__title">${Lampa.Lang.translate('halloween_title')}</div>
            <div class="halloween__details">${Lampa.Lang.translate('halloween_details')}</div>
        </div>`)

        let enabled = Lampa.Controller.enabled().name

        Lampa.Modal.open({
            title: '',
            html: html,
            size: 'medium',
            nopadding: true,
            onBack: ()=>{
                Lampa.Modal.close()

                Lampa.Controller.toggle(enabled)
            }
        })

        let img = html.find('.halloween__img')

        Lampa.Utils.imgLoad(img[0], Lampa.Utils.protocol() + Lampa.Manifest.cub_domain + '/img/other/halloween.jpg', ()=>{
            img.addClass('--loaded')
        }, ()=>{
            html.find('.halloween__image').remove()
        })

        Lampa.Modal.scroll().render(true).addClass('scroll--nopadding')
    }

    function button(){
        Lampa.Lang.add({
            halloween_title: {
                ru: '22% скидка на Хэллоуин!',
                uk: '22% знижка на Хелловін!',
                be: '22% зніжка на Хэлоўін!',
                en: '22% off for Halloween!',
            },
            halloween_details: {
                ru: 'Убей цены — воскреси выгоду! Акция действует с 25 по 31 октября. Оформите подписку <b>CUB Premium</b> со скидкой, подробнее на сайте <span>{site}/premium</span>',
                uk: 'Вбий ціни — воскреси вигоду! Акція діє з 25 по 31 жовтня. Оформіть підписку <b>CUB Premium</b> зі знижкою, детальніше на сайті <span>{site}/premium</span>',
                be: 'Забі цэны — уваскрасі выгаду! Акцыя дзейнічае з 25 па 31 кастрычніка. Аформіце падпіску <b>CUB Premium</b> са зніжкай, падрабязней на сайце <span>{site}/premium</span>',
                en: 'Kill the prices, resurrect the savings! The offer is valid from October 25 to 31. Get a <b>CUB Premium</b> subscription at a discount, more details at <span>{site}/premium</span>',
            },
        })

        let button = $(`<div class="head__action head__settings selector halloween__button">
            <svg width="21" height="21" viewBox="0 0 21 21" fill="none" xmlns="http://www.w3.org/2000/svg">
                <path d="M5.33371 6.78659e-05C5.15455 -0.00176186 4.9774 0.0378448 4.81608 0.115795C4.65476 0.193745 4.51365 0.307929 4.40375 0.44943C4.26687 0.627429 4.18482 0.841453 4.16763 1.06534C4.15043 1.28922 4.19884 1.51326 4.30694 1.71007L5.15465 3.24727C6.00272 2.0765 7.33033 1.21074 8.88211 0.862705L5.59812 0.0354617C5.51155 0.0133755 5.42304 0.00149679 5.33371 6.78659e-05ZM15.4862 6.78659e-05C15.3992 0.00122453 15.3111 0.0130225 15.2218 0.0354617L11.9374 0.862705C13.4899 1.21074 14.8172 2.0765 15.6649 3.24693L16.5129 1.70973C16.6211 1.51302 16.6695 1.28908 16.6525 1.06527C16.6354 0.84146 16.5535 0.627465 16.4168 0.44943C16.3069 0.307835 16.1656 0.193594 16.0042 0.11564C15.8427 0.0376857 15.6654 -0.00186923 15.4862 6.78659e-05ZM10.4099 1.38806C7.31749 1.38806 4.85797 3.58386 4.85797 6.24603C4.85797 8.9082 7.31749 11.104 10.4099 11.104C13.5024 11.104 15.9619 8.9082 15.9619 6.24603C15.9619 3.58386 13.5024 1.38806 10.4099 1.38806ZM8.32795 3.81705C8.74053 3.81705 9.1028 4.04363 9.34188 4.36253C9.58096 4.68142 9.71594 5.09816 9.71594 5.55204C9.71594 6.00591 9.58096 6.42265 9.34188 6.74154C9.1028 7.06044 8.74053 7.28703 8.32795 7.28703C7.91537 7.28703 7.55345 7.06044 7.31402 6.74154C7.07459 6.42265 6.93996 6.00591 6.93996 5.55204C6.93996 5.09816 7.07494 4.68142 7.31402 4.36253C7.5531 4.04363 7.91537 3.81705 8.32795 3.81705ZM12.4919 3.81705C12.9045 3.81705 13.2668 4.04363 13.5059 4.36253C13.7449 4.68142 13.8799 5.09816 13.8799 5.55204C13.8799 6.00591 13.7449 6.42265 13.5059 6.74154C13.2668 7.06044 12.9045 7.28703 12.4919 7.28703C12.0793 7.28703 11.7174 7.06044 11.478 6.74154C11.2386 6.42265 11.1039 6.00591 11.1039 5.55204C11.1039 5.09816 11.2389 4.68142 11.478 4.36253C11.7171 4.04363 12.0793 3.81705 12.4919 3.81705ZM4.16398 5.89903C1.86858 5.89903 0 7.76762 0 10.063C0 10.6345 0.458037 11.0808 1.00248 11.1394C1.96783 11.2431 2.92485 11.5829 3.59872 12.1471C4.27259 12.7113 4.6817 13.4754 4.61195 14.5587C4.5946 14.8231 4.66955 15.0886 4.85381 15.2728C5.03841 15.4567 5.30699 15.5313 5.57313 15.5098C6.85009 15.4075 7.95215 15.9533 8.76031 16.8791C9.56847 17.8049 10.0629 19.1113 10.0629 20.4729C10.0629 20.565 10.0995 20.6532 10.1646 20.7183C10.2296 20.7834 10.3179 20.8199 10.4099 20.8199C10.502 20.8199 10.5902 20.7834 10.6553 20.7183C10.7204 20.6532 10.7569 20.565 10.7569 20.4729C10.7569 19.1145 11.2486 17.8108 12.0533 16.8857C12.8584 15.9602 13.9563 15.4113 15.228 15.5078C15.4994 15.5286 15.7718 15.4522 15.9591 15.2649C16.1465 15.0782 16.2228 14.8086 16.2065 14.5386C16.1427 13.4625 16.5535 12.703 17.2271 12.1415C17.9006 11.5801 18.8545 11.2428 19.8174 11.1391C20.3618 11.0804 20.8199 10.6342 20.8199 10.0627C20.8199 7.76727 18.9513 5.89869 16.6559 5.89869V6.24569C16.6559 9.33293 13.8334 11.7977 10.4099 11.7977C6.98646 11.7977 4.16398 9.33293 4.16398 6.24569V5.89903ZM8.67495 7.98102H12.1449C12.237 7.98102 12.3252 8.01758 12.3903 8.08265C12.4554 8.14773 12.4919 8.23599 12.4919 8.32802C12.4919 8.42005 12.4554 8.50831 12.3903 8.57338C12.3252 8.63846 12.237 8.67502 12.1449 8.67502H11.7979V9.02202C11.7979 9.11405 11.7614 9.20231 11.6963 9.26738C11.6312 9.33246 11.543 9.36901 11.4509 9.36901C11.3589 9.36901 11.2706 9.33246 11.2056 9.26738C11.1405 9.20231 11.1039 9.11405 11.1039 9.02202V8.67502H9.71594V9.02202C9.71594 9.11405 9.67938 9.20231 9.61431 9.26738C9.54923 9.33246 9.46097 9.36901 9.36894 9.36901C9.27691 9.36901 9.18865 9.33246 9.12358 9.26738C9.05851 9.20231 9.02195 9.11405 9.02195 9.02202V8.67502H8.67495C8.58292 8.67502 8.49466 8.63846 8.42958 8.57338C8.36451 8.50831 8.32795 8.42005 8.32795 8.32802C8.32795 8.23599 8.36451 8.14773 8.42958 8.08265C8.49466 8.01758 8.58292 7.98102 8.67495 7.98102Z" fill-rule="evenodd" clip-rule="evenodd" fill="currentColor"/>
            </svg>
        </div>`)

        button.on('hover:enter', show)

        setInterval(()=>{
            if(Lampa.Player.opened()) return

            button.addClass('--animate')

            setTimeout(()=>{
                button.removeClass('--animate')
            },2000)
        },1000 * 10)

        Lampa.Head.render().find('.open--search').after(button)
    }

    function add(){
        let logo = $(`<div class="head__logo-icon head__logo-halloween">
            <div class="head__logo-halloween-fire"></div>
            <div class="head__logo-halloween-svg">
                <svg width="512" height="494" viewBox="0 0 512 494" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M247.135 95.8686C247.135 95.8686 253.636 43.2644 279.052 22.5773C304.467 1.89026 322.199 0.117081 322.199 0.117081L350.57 30.2611C350.57 30.2611 277.279 52.7213 272.55 120.693C268.413 189.256 247.135 95.8686 247.135 95.8686Z" fill="#68AA00"/>
                    <path fill-rule="evenodd" clip-rule="evenodd" d="M501.29 205.214C523.159 272.004 509.565 351.797 464.644 413.267C447.504 437.5 426.817 456.414 404.947 468.826C383.078 481.83 360.027 488.331 336.976 488.331C325.154 488.331 312.742 486.558 300.921 482.421L296.784 481.239L293.237 483.603C271.959 497.788 242.997 497.197 221.719 482.421L218.173 480.057L214.035 481.239C201.032 485.967 188.029 488.331 174.435 488.331C128.332 488.331 81.6383 460.552 46.7659 412.676C2.43651 351.206 -11.7489 271.413 10.1203 204.623C37.9 123.057 99.9612 105.325 147.246 105.325C180.316 105.325 207.326 113.717 213.37 115.595C214.132 115.831 214.56 115.965 214.626 115.965L218.764 117.147L222.31 114.782C243.588 100.006 272.55 99.4149 293.828 113.6L297.375 115.965L300.921 114.782C310.378 111.827 334.611 105.325 364.164 105.325C412.04 105.325 474.101 123.057 501.29 205.214ZM117.102 193.393L225.266 238.905C224.674 239.496 153.747 310.423 117.102 193.393ZM360.027 361.254L380.123 382.532L446.321 281.461L380.123 323.426L360.027 302.148L294.419 345.295L256.001 313.378L217.582 345.295L151.974 302.148L131.287 323.426L65.6797 281.461L131.287 382.532L151.974 361.254L217.582 404.401L256.001 372.484L294.419 404.401L360.027 361.254ZM401.401 193.393L293.237 238.905C293.237 239.496 364.755 310.423 401.401 193.393Z" fill="#F27503"/>
                    <path d="M297.375 481.83L301.512 483.012C313.333 486.558 325.154 488.922 337.567 488.922C360.618 488.922 384.26 481.83 405.538 469.418C427.407 456.414 447.503 437.5 465.235 413.858C509.565 352.388 523.75 272.595 501.881 205.805C474.101 123.057 412.04 105.326 364.755 105.326C335.202 105.326 310.378 111.827 301.512 114.782L297.375 115.965C297.375 115.965 367.119 140.789 401.401 193.393C401.401 193.393 401.401 193.393 401.401 193.393C416.236 216.082 428.736 251.977 430.192 291.686L446.321 281.461L430.227 306.034C428.159 370.406 395.544 441.591 297.375 481.83Z" fill="#D35C02"/>
                </svg>
            </div>
        </div>`)

        $('.head .head__logo-icon').replaceWith($(logo))

        $('body').append(`<style>@@include('../plugins/halloween/css/style.css')</style>`)

        logo.on('mousedown', ()=>{
            Lampa.Menu.toggle()
        })

        if(Lampa.Lang.selected(['ru','uk','be','en']) && !window.lampa_settings.iptv) button()
    }

    if(window.appready) add()
    else{
        Lampa.Listener.follow('app', function (e) {
            if (e.type == 'ready') add()
        })
    }
}

if(!window.plugin_halloween_ready){
    window.plugin_halloween_ready = true

    pluginHalloween()
}
